class Solution {
public:
    int maxStarSum(std::vector<int>& vals, std::vector<std::vector<int>>& edges, int k) {
        int n = vals.size();
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            int u = e[0], v = e[1];
            if (vals[v] > 0) adj[u].push_back(vals[v]);
            if (vals[u] > 0) adj[v].push_back(vals[u]);
        }
        int ans = *std::max_element(vals.begin(), vals.end());
        for (int i = 0; i < n; ++i) {
            std::sort(adj[i].rbegin(), adj[i].rend());
            int cur = vals[i];
            int limit = std::min((int)adj[i].size(), k);
            for (int j = 0; j < limit; ++j) cur += adj[i][j];
            ans = std::max(ans, cur);
        }
        return ans;
    }
};

class Solution {
    public int maxStarSum(int[] vals, int[][] edges, int k) {
        int n = vals.length;
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            if (vals[v] > 0) adj[u].add(vals[v]);
            if (vals[u] > 0) adj[v].add(vals[u]);
        }
        int ans = vals[0];
        for (int v : vals) ans = Math.max(ans, v);
        for (int i = 0; i < n; i++) {
            adj[i].sort(java.util.Collections.reverseOrder());
            int cur = vals[i];
            int limit = Math.min(adj[i].size(), k);
            for (int j = 0; j < limit; j++) cur += adj[i].get(j);
            ans = Math.max(ans, cur);
        }
        return ans;
    }
}

var maxStarSum = function(vals, edges, k) {
    const n = vals.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        if (vals[v] > 0) adj[u].push(vals[v]);
        if (vals[u] > 0) adj[v].push(vals[u]);
    }
    let ans = Math.max(...vals);
    for (let i = 0; i < n; i++) {
        adj[i].sort((a, b) => b - a);
        let cur = vals[i];
        const limit = Math.min(adj[i].length, k);
        for (let j = 0; j < limit; j++) cur += adj[i][j];
        if (cur > ans) ans = cur;
    }
    return ans;
};
